SELECT CAST(SUM(CASE WHEN DOC = '54' THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN DOC = '52' THEN 1 ELSE 0 END), 0) AS ratio
FROM schools
WHERE County = 'Orange' AND StatusType = 'Merged';

SELECT SUM(p.publisher_name = 'Marvel Comics') - SUM(p.publisher_name = 'DC Comics') AS superhero_count_difference
FROM superhero AS s
JOIN publisher AS p ON s.publisher_id = p.id;
